public int findMaxConsecutive(int[] arr) {
    // Define the result for an empty array.
    if (arr == null || arr.length == 0) {
        return 0;
    }

    // A single element is a run of length 1.
    int currentCount = 1;
    int maxCount = 1;

    // Start at 1 so that arr[i - 1] is always valid.
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] == arr[i - 1]) {
            // The current run continues.
            currentCount++;
        } else {
            // A new run begins with the current element.
            currentCount = 1;
        }

        // Save the largest run found so far.
        if (currentCount > maxCount) {
            maxCount = currentCount;
        }
    }

    return maxCount;
}
