public static String alphaNumSwap(
        String word, int[] swap, int[] replacement) {

    // The entire input word must be alphanumeric.
    for (int k = 0; k < word.length(); k++) {
        if (!Character.isLetterOrDigit(word.charAt(k))) {
            return word;
        }
    }

    char[] result = word.toCharArray();

    for (int k = 0; k < word.length(); k++) {
        char originalChar = word.charAt(k);

        for (int i = 0; i < swap.length; i++) {
            if (originalChar == (char) swap[i]) {
