public Double[] getRoots() {
    double discriminant = b * b - 4 * a * c;

    if (discriminant > 0) {
        double sqrtD = Math.sqrt(discriminant);

        return new Double[] {
            (-b + sqrtD) / (2 * a),
            (-b - sqrtD) / (2 * a)
